-- Ehrungen & Orden – initiale Befuellung aus dem Ehrungs-Kompendium (Arbeitsgrundlage)
--
-- Uebernommen wird ausschliesslich, was im Kompendium steht. Nichts wurde ergaenzt oder erfunden:
-- * 38 Organisationen: BDK (Dachverband), 35 Regionalverbaende, 2 unabhaengige Traditionsverbaende
-- * BDK-Verdienstorden Silber (15 J.) und Gold (25 J.) mit Regel "aktive Taetigkeit"; Gold mit Brillanten nur manuell
--   (Einzelfallpruefung laut Kompendium)
-- * Spitzenorden der Regionalverbaende nur als Name, ohne Kriterien (im Kompendium keiner Auszeichnung zugeordnet)
-- Alle Eintraege: Pruefstatus "nicht_geprueft". Auffaelligkeiten stehen in pruef_bemerkung.
-- Idempotent: bereits vorhandene Eintraege (gleicher Name) werden nicht doppelt angelegt.

insert into public.ehrungs_organisationen (name, kuerzel, art, beschreibung, quelle, pruefstatus, verband_id) values
  ('Bund Deutscher Karneval e.V.', 'BDK', 'dachverband', 'Dachverband; stellt die übergeordneten Richtlinien. Seine Orden überlagern die regionalen Systeme.', 'Ehrungs-Kompendium „Gesamtkompendium: Auszeichnungen & Orden im deutschen Karneval“ – Arbeitsgrundlage, nicht auf Aktualität/Fehlerfreiheit geprüft (übernommen am 26.09.2026)', 'nicht_geprueft', (select v.id from public.verbaende v where v.kuerzel = 'BDK'))
on conflict (name) do nothing;

