insert into public.ehrungs_organisationen (name, kuerzel, art, beschreibung, quelle, pruefstatus) values
  ('Vereinigung Schwäbisch-Alemannischer Narrenzünfte e.V.', 'VSAN', 'traditionsverband', 'Laut Kompendium: Keine Vergabe nach mathematischen Punkten oder Kampagnen-Dienstzeit. Die Ehrung erfolgt ausschließlich über die jahrzehntelange Treue zur eigenen Narrenzunft, die Weitergabe des Schnitzhandwerks für Holzmasken oder das Tragen des Häses (Traditionskostüm). Höchste Auszeichnungen sind meist rein ideeller Natur oder handgeschnitzte Unikate.', 'Ehrungs-Kompendium „Gesamtkompendium: Auszeichnungen & Orden im deutschen Karneval“ – Arbeitsgrundlage, nicht auf Aktualität/Fehlerfreiheit geprüft (übernommen am 26.09.2026)', 'nicht_geprueft'),
  ('Kölner Festkomitee von 1823 e.V.', null, 'traditionsverband', 'Laut Kompendium: Obwohl eng mit dem BDK verzahnt, besitzt das Festkomitee Kölner Karneval ein autonomes Vergabesystem für den Verdienstorden des Kölner Karnevals. Hier zählt vor allem der strukturelle Beitrag zum Erhalt des Kölner Ur-Brauchtums und die Arbeit in den Kölner Traditionskorps.', 'Ehrungs-Kompendium „Gesamtkompendium: Auszeichnungen & Orden im deutschen Karneval“ – Arbeitsgrundlage, nicht auf Aktualität/Fehlerfreiheit geprüft (übernommen am 26.09.2026)', 'nicht_geprueft')
on conflict (name) do nothing;

