join public.ehrungs_organisationen o on o.name = x.organisation
where not exists (select 1 from public.ehrungsarten a where a.typ = 'verband' and a.organisation_id = o.id and a.name = x.name);

insert into public.ehrungs_regeln (ehrungsart_id, berechnung, jahre, bemerkung)
select a.id, x.berechnung, x.jahre, x.bemerkung
from (values
  ('Verdienstorden in Silber', 'aktiv', 15::numeric, 'Laut Kompendium: 15 Jahre aktive Arbeit'),
  ('Verdienstorden in Gold', 'aktiv', 25::numeric, 'Laut Kompendium: 25 Jahre aktive Arbeit'),
  ('Verdienstorden in Gold mit Brillanten', 'manuell', null::numeric, 'Laut Kompendium: 40 Jahre ununterbrochen, Einzelfallprüfung')
) x(name, berechnung, jahre, bemerkung)
join public.ehrungsarten a on a.name = x.name and a.typ = 'verband'
join public.ehrungs_organisationen o on o.id = a.organisation_id and o.name = 'Bund Deutscher Karneval e.V.'
where not exists (select 1 from public.ehrungs_regeln r where r.ehrungsart_id = a.id);
